namespace Invest.Sign.Router.Core.Model;

/// <summary>A stage of a route instance, created on stage entry. Mirrors <c>SGN_STAGE_INSTANCE</c>.</summary>
public sealed record StageInstance
{
    public required long Id { get; init; }

    public required long RouteInstanceId { get; init; }

    public required string StageKey { get; init; }

    public required StageState State { get; init; }

    /// <summary>Signing request id generated by the service. Unique.</summary>
    public required string RequestId { get; init; }

    public DateTimeOffset? RequestedAt { get; init; }

    public DateTimeOffset? DeadlineAt { get; init; }

    public DateTimeOffset? FinishedAt { get; init; }

    /// <summary>Rejection or error reason.</summary>
    public string? Reason { get; init; }
}
